import express from "express";
import { fileURLToPath } from "node:url";
import {
  connectDB,
  getAllCourses,
  findCoursesByCategory,
  findShortCourses,
  getThreeCostliestCourses,
  addCourse,
} from "./database.js";

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(express.static(fileURLToPath(new URL("./public", import.meta.url))));

function sendList(res, data, functionName) {
  if (!Array.isArray(data)) {
    return res.status(500).json({
      error: `${functionName}() did not return a list from the database. Complete it in database.js.`,
    });
  }
  res.json(data);
}

app.get("/api/courses", async (req, res) => {
  try {
    sendList(res, await getAllCourses(), "getAllCourses");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/courses/search", async (req, res) => {
  try {
    sendList(res, await findCoursesByCategory(req.query.category), "findCoursesByCategory");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/courses/filter", async (req, res) => {
  const maxWeeks = Number(req.query.maxWeeks);
  if (Number.isNaN(maxWeeks)) {
    return res.status(400).json({ error: "Please enter a number." });
  }
  try {
    sendList(res, await findShortCourses(maxWeeks), "findShortCourses");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/courses/top", async (req, res) => {
  try {
    sendList(res, await getThreeCostliestCourses(), "getThreeCostliestCourses");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post("/api/courses", async (req, res) => {
  try {
    const saved = await addCourse(req.body);
    if (!saved) {
      return res.status(500).json({
        error: "addCourse() did not return the saved course. Complete it in database.js.",
      });
    }
    res.status(201).json(saved);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

try {
  await connectDB();
} catch (err) {
  console.log("Could not connect to MongoDB:", err.message);
}

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
